WHERE {
  {
    ns:m.01wv9xn ns:music.musical_group.member ?y .
    ?y ns:music.group_membership.member ?x ;
       ns:music.group_membership.role ns:m.0290ngj . #vocals
  }
  UNION
  {
    ns:m.01wv9xn ns:music.musical_group.member ?y .
    ?y ns:music.group_membership.member ?x ;
       ns:music.group_membership.role ns:m.0_sv_90 . #lead vocals
  }?x ns:influence.influence_node.influenced_by ns:m.015hws . 
}

PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
#MANUAL SPARQL
PREFIX ns: <http://rdf.freebase.com/ns/>
SELECT DISTINCT ?x 
WHERE {
	FILTER (?x != ns:m.0d05w3)
	{ 
	  ns:m.0d05w3 ns:location.statistical_region.places_exported_to ?y .
	  ?y ns:location.imports_and_exports.exported_to ?x . 
	}
	UNION
	{
	  ns:m.0d05w3 ns:location.statistical_region.places_imported_from ?y .
	  ?y ns:location.imports_and_exports.imported_from ?x . 
	}?x ns:event.speech_topic.speeches_or_presentations_on_this_topic ?c .
?c ns:event.speech_or_presentation.speaker_s ns:m.08ngt98 . 
}

PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
#MANUAL SPARQL
PREFIX ns: <http://rdf.freebase.com/ns/>
SELECT DISTINCT ?x 
WHERE {
	FILTER (?x != ns:m.0hzlz)
	{ 
	  ns:m.0hzlz ns:location.statistical_region.places_exported_to ?y .
	  ?y ns:location.imports_and_exports.exported_to ?x . 
	}
	UNION
	{
	  ns:m.0hzlz ns:location.statistical_region.places_imported_from ?y .
	  ?y ns:location.imports_and_exports.imported_from ?x . 
	}?x ns:location.country.calling_code "255" . 
}

PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
#MANUAL SPARQL
PREFIX ns: <http://rdf.freebase.com/ns/>
SELECT DISTINCT ?x
WHERE {
  {
    ns:m.0bx_x85 ns:sports.sports_championship_event.champion ?x .
  }
  UNION
  {
    ns:m.0bx_x85 ns:sports.sports_championship_event.runner_up ?x . 
  }?x ns:sports.sports_team.founded "1947"^^xsd:gYear . 
}

PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>
#MANUAL SPARQL
PREFIX ns: <http://rdf.freebase.com/ns/>
SELECT DISTINCT  ?x
WHERE
{ 
  {
    SELECT ?pfrom ?pto
    WHERE {
      ns:m.083q7 ns:government.politician.government_positions_held ?y0 .  # Woodrow Wilson  
      ?y0 ns:government.government_position_held.basic_title ns:m.060c4 ;  # President
          ns:government.government_position_held.from ?pfrom ;
          ns:government.government_position_held.to ?pto .
    }
  }
  {
    SELECT ?from ?to ?x
    WHERE {
      ?x ns:common.topic.notable_types ns:m.02h76fz . # Military Conflict
      ?x ns:time.event.start_date ?from . 
      ?x ns:time.event.end_date ?to . 
      ?x ns:military.military_conflict.combatants ?y .
      ?y ns:military.military_combatant_group.combatants ns:m.09c7w0 .  # United States of America
    }
  }
  FILTER (?to <= ?pto && ?from >= ?pfrom) ?x ns:military.military_conflict.commanders ?c .
?c ns:military.military_command.military_commander ns:m.015xww . 
}

